def test_agent_cli_install_entries_unchanged():
    actual = [dataclasses.asdict(d) for d in DEPS if d.group == "agent_cli"]
    # asdict keeps tuples; the snapshot stores lists — normalize before comparing.
    actual = [
        {k: list(v) if isinstance(v, tuple) else v for k, v in entry.items()}
        for entry in actual
    ]
    assert actual == SNAPSHOT
